-- Audit the selected official search candidate; legacy mappings retain null provenance.
ALTER TABLE legal_wiki.reference_job_mappings ADD COLUMN confirmed_tenant text, ADD COLUMN lookup_query text, ADD COLUMN lookup_candidate_sha256 text, ADD CONSTRAINT reference_lookup_audit_pair CHECK ((confirmed_tenant IS NULL AND lookup_query IS NULL AND lookup_candidate_sha256 IS NULL) OR (confirmed_tenant IS NOT NULL AND length(btrim(confirmed_tenant))>0 AND lookup_query IS NOT NULL AND length(btrim(lookup_query))>0 AND lookup_candidate_sha256 IS NOT NULL AND lookup_candidate_sha256 ~ '^[0-9a-f]{64}$'));
